def __TEMPLATE_MAIN__(mode: str = "report", publish: str = "no", lookback_days: int = 0) -> dict:
    """Entry point. Kept at the top so the Builder Test playground detects the parameters; the logic is in _run_tool."""
    result = _run_tool(mode, publish, lookback_days)
    return _fit(result, (mode or "report").strip().lower() if isinstance(mode, str) else "report")


