DAYS_LEFT_RE = re.compile(r"(?i)(days?_?(left|until|remaining|to_?expir\w*)|dias_?restantes)$")


def _dt(key):
    return DESIGN_TEXT.get(CONFIG.get("language", "es"), DESIGN_TEXT["en"])[key]


def _rgb(color):
    color = str(color).lstrip("#")
    return tuple(int(color[i:i + 2], 16) for i in (0, 2, 4))


def _hexc(rgb):
    return "#%02x%02x%02x" % tuple(max(0, min(255, int(round(v)))) for v in rgb)


def _mix(a, b, t):
    return _hexc([x + (y - x) * t for x, y in zip(_rgb(a), _rgb(b))])


def _lum(color):
    def channel(v):
        v /= 255
        return v / 12.92 if v <= 0.03928 else ((v + 0.055) / 1.055) ** 2.4
    r, g, b = (channel(v) for v in _rgb(color))
    return 0.2126 * r + 0.7152 * g + 0.0722 * b


def _contrast(a, b):
    hi, lo = sorted((_lum(a), _lum(b)), reverse=True)
    return (hi + 0.05) / (lo + 0.05)


def _toward(color, target, ratio, against):
    """Mix `color` toward `target` until it reaches `ratio` contrast against `against` (WCAG)."""
    for step in range(21):
        candidate = _mix(color, target, step / 20)
        if _contrast(candidate, against) >= ratio:
            return candidate
    return target


def _rgba(color, alpha):
    r, g, b = _rgb(color)
    return f"rgba({r},{g},{b},{alpha})"


def _hexok(value):
    return isinstance(value, str) and re.match(r"^#[0-9a-fA-F]{6}$", value) is not None


def _theme():
    brand = CONFIG.get("brand") or {}
    primary = brand.get("primary") if _hexok(brand.get("primary")) else (CONFIG.get("accent") if _hexok(CONFIG.get("accent")) and CONFIG.get("accent") != "#0f6cbd" else "#0e2a47")
    accent = brand.get("accent") if _hexok(brand.get("accent")) else ("#0f6cbd" if primary == "#0e2a47" else primary)
    dark = brand.get("dark") if _hexok(brand.get("dark")) else None
    mode = brand.get("hero", "auto")
    white, black, near = "#ffffff", "#000000", "#101418"
    if mode not in ("brand", "dark", "light"):
        mode = "brand" if _contrast(white, primary) >= 4.5 else "dark" if dark and _contrast(accent, dark) >= 4.5 else "light"
    paper = _mix("#f5f6f8", primary, 0.03)
    ink = _mix(near, primary, 0.12)
    line = _mix(_mix(white, primary, 0.14), "#e4e7ec", 0.55)
    muted = _toward(_mix("#5d6673", primary, 0.12), near, 4.6, paper)
    title = _toward(primary, black, 4.6, white) if _contrast(white, primary) >= 4.5 else ink
    link = _toward(primary, black, 4.6, white)
    chart = primary if _contrast(primary, white) >= 3 else _toward(primary, black, 3, white)
    btn = accent
    btn_ink = white if _contrast(white, btn) >= _contrast(near, btn) else near
    if _contrast(btn_ink, btn) < 4.5:
        btn, btn_ink = _toward(accent, black, 4.6, white), white
    tokens = {"paper": paper, "ink": ink, "line": line, "line2": _mix(line, ink, 0.18), "muted": muted, "title": title,
              "link": link, "chart": chart, "btn": btn, "btn-ink": btn_ink, "soft": _mix("#f6f7f9", primary, 0.05),
              "hover": _mix(white, primary, 0.03), "focus": link, "focus-ring": _rgba(link, 0.22),
              "accent-soft": _rgba(accent, 0.28), "shadow": f"0 1px 2px {_rgba(ink, 0.05)},0 12px 32px {_rgba(ink, 0.07)}"}
    if mode == "light":
        hero = {"hero-bg": f"linear-gradient(160deg,{white} 0%,{white} 45%,{_mix(white, accent, 0.10)} 100%)", "hero-ink": ink,
                "hero-title": title if title != ink else _toward(primary, black, 4.6, white), "hero-muted": muted, "hero-line": line,
                "hero-glow": _rgba(accent, 0.16), "hero-stripe": primary}
        tones = {"crit": ("#b42318", "#fef3f2", "#fecdca"), "warn": ("#b54708", "#fffaeb", "#fedf89"), "ok": ("#067647", "#ecfdf3", "#abefc6")}
    else:
        base = primary if mode == "brand" else dark or _mix(primary, near, 0.82)
        if _contrast(white, base) < 4.5:
            base = _toward(base, black, 4.5, white)
        hero_muted = _toward(_mix(base, white, 0.74), white, 4.6, base)
        hero = {"hero-bg": f"linear-gradient(150deg,{base} 0%,{_mix(base, black, 0.18)} 100%)", "hero-ink": white,
                "hero-title": white, "hero-muted": hero_muted, "hero-line": _rgba(white, 0.2),
                "hero-glow": _rgba(accent if accent != primary else white, 0.22), "hero-stripe": accent if _contrast(accent, base) >= 3 else _rgba(white, 0.5)}
        tones = {"crit": (_toward("#ffb4ab", white, 4.5, base), _rgba(white, 0.08), _rgba("#ffb4ab", 0.5)),
                 "warn": (_toward("#fedf89", white, 4.5, base), _rgba(white, 0.08), _rgba("#fedf89", 0.5)),
                 "ok": (_toward("#a6f4c5", white, 4.5, base), _rgba(white, 0.08), _rgba("#a6f4c5", 0.45))}
    tokens.update(hero)
    tokens.update({"bar-bg": "#ffffff", "bar-ink": ink, "bar-muted": muted, "bar-line": line, "bar-title": title})
    if brand.get("logo_on_dark"):
        bar = primary if _contrast(white, primary) >= 4.5 else dark or _toward(primary, black, 4.5, white)
        tokens.update({"bar-bg": bar, "bar-ink": white, "bar-muted": _toward(_mix(bar, white, 0.75), white, 4.6, bar),
                       "bar-line": _rgba(white, 0.25), "bar-title": white})
    preset = brand.get("font") if brand.get("font") in ("plex", "nunito", "fira") else "plex"
    family = {"plex": "Report Sans", "nunito": "Nunito Sans", "fira": "Fira Sans"}[preset]
    tokens["font"] = f"'{family}','Segoe UI',system-ui,-apple-system,sans-serif"
    tokens["display-w"] = str({"plex": 700, "nunito": 900, "fira": 600}[preset])
    return mode, tokens, tones


