# ----------------------------------------------------------------------------- run generated code
class _NoNetwork:
    class RequestException(Exception):
        pass

    def __getattr__(self, name):
        def blocked(*args, **kwargs):
            raise RuntimeError("network blocked during self_test")
        return blocked


def _load(code, offline):
    ns = {"__name__": "generated_tool"}
    with contextlib.redirect_stdout(io.StringIO()):
        exec(compile(code, "generated_tool.py", "exec"), ns)  # noqa: S102 - kit runs only code it generated itself
    if offline:
        ns["requests"] = _NoNetwork()
    return ns


def _run(code, mode):
    started = time.time()
    try:
        ns = _load(code, offline=(mode == "self_test"))
        with contextlib.redirect_stdout(io.StringIO()):
            result = ns.get("_run_tool", ns["main"])(mode=mode, publish="no")
        return ns, result, round(time.time() - started, 1)
    except Exception as exc:
        return None, {"status": "CRASH", "error": f"{type(exc).__name__}: {exc}", "trace": traceback.format_exc()[-1500:]}, round(time.time() - started, 1)


def _rule_coverage(ns, config):
    now = ns["_now"]()
    data = {s["id"]: ns["_selftest_collect"](s, now)[0] for s in config["sources"]}
    ns["_derive"](data, now)
    findings, _ = ns["_findings"](data, now)
    fired = sorted({f["rule"] for f in findings})
    return fired, [r["id"] for r in config["rules"] if r["id"] not in fired]


def _field_check(config, discover):
    by_source = {s["id"]: s for s in (discover or {}).get("sources", [])}
    derived = {(d["dataset"], d["name"]) for d in config.get("derive", [])}
    report = []
    for dataset, fields in _referenced_fields(config).items():
        live = by_source.get(dataset) or {}
        if live.get("status") != "OK":
            report.append({"dataset": dataset, "status": "NOT_CHECKED", "reason": live.get("error") or "source not read"})
            continue
        cols = [c["name"] for c in live.get("columns", [])]
        if not cols:
            report.append({"dataset": dataset, "status": "NO_ROWS", "reason": "source returned 0 rows in discover; fields cannot be verified"})
            continue
        missing = []
        for field, used in fields.items():
            if field not in cols and (dataset, field) not in derived:
                missing.append({"field": field, "used_by": used, "did_you_mean": difflib.get_close_matches(field, cols, n=3, cutoff=0.5)})
        report.append({"dataset": dataset, "status": "OK" if not missing else "MISSING_FIELDS", "missing": missing, "live_columns": cols[:60]})
    return report


# ----------------------------------------------------------------------------- environment
def _jwt_claims(token):
    try:
        part = token.split(".")[1]
        return json.loads(base64.urlsafe_b64decode(part + "=" * (-len(part) % 4)))
    except Exception:
        return {}


def _environment():
    import requests
    from azure.identity import ManagedIdentityCredential
    out = {"identity": {}, "errors": []}
    client_id = os.environ.get("AZURE_CLIENT_ID", "")
    if not client_id:
        return {"status": "NO_IDENTITY", "message": "AZURE_CLIENT_ID is not set: run this inside the Azure SRE Agent."}
    cred = ManagedIdentityCredential(client_id=client_id)

    def get(url, scope="https://management.azure.com/.default", method="GET", body=None):
        tok = cred.get_token(scope).token
        resp = requests.request(method, url, headers={"Authorization": "Bearer " + tok}, json=body, timeout=60)
        if resp.status_code >= 400:
            raise RuntimeError(f"HTTP {resp.status_code} {url.split('?')[0]}: {resp.text[:200]}")
        return resp.json()

    try:
        claims = _jwt_claims(cred.get_token("https://management.azure.com/.default").token)
        out["identity"] = {"client_id": client_id, "principal_id": claims.get("oid"), "tenant_id": claims.get("tid")}
    except Exception as exc:
        return {"status": "AUTH_FAILED", "message": f"{type(exc).__name__}: {str(exc)[:300]}"}
    subs = []
    try:
        subs = [{"id": s["subscriptionId"], "name": s.get("displayName")} for s in get(ARM + "/subscriptions?api-version=2022-12-01").get("value", [])]
    except Exception as exc:
        out["errors"].append(f"subscriptions: {exc}")
    out["subscriptions"] = subs

    def arg(query):
        body = {"subscriptions": [s["id"] for s in subs][:1000], "query": query, "options": {"$top": 1000}}
        return get(ARM + "/providers/Microsoft.ResourceGraph/resources?api-version=2022-10-01", method="POST", body=body).get("data", [])

    if subs:
        queries = {
            "log_analytics_workspaces": "resources | where type =~ 'microsoft.operationalinsights/workspaces' | project name, resourceGroup, subscriptionId, location, customerId = tostring(properties.customerId), id",
            "storage_accounts": "resources | where type =~ 'microsoft.storage/storageaccounts' | project name, resourceGroup, subscriptionId, id",
            "kusto_clusters": "resources | where type =~ 'microsoft.kusto/clusters' | project name, resourceGroup, uri = tostring(properties.uri), id",
            "top_resource_types": "resources | summarize count_ = count() by type | top 25 by count_",
        }
        for key, query in queries.items():
            try:
                out[key] = arg(query)
            except Exception as exc:
                out["errors"].append(f"{key}: {exc}")
    roles, names = [], {}
    for sub in subs[:25]:
        try:
            url = f"{ARM}/subscriptions/{sub['id']}/providers/Microsoft.Authorization/roleAssignments?api-version=2022-04-01&$filter=assignedTo('{out['identity']['principal_id']}')"
            for ra in get(url).get("value", []):
                rd = ra["properties"]["roleDefinitionId"]
                if rd not in names:
                    try:
                        names[rd] = get(ARM + rd + "?api-version=2022-04-01")["properties"]["roleName"]
                    except Exception:
                        names[rd] = rd.split("/")[-1]
                roles.append({"role": names[rd], "scope": ra["properties"]["scope"]})
        except Exception as exc:
            out["errors"].append(f"role assignments {sub['id']}: {str(exc)[:160]}")
    out["azure_roles"] = list({(r["role"], r["scope"]): r for r in roles}.values())
    try:
        out["graph_app_roles"] = sorted(_jwt_claims(cred.get_token("https://graph.microsoft.com/.default").token).get("roles", []))
    except Exception as exc:
        out["graph_app_roles"] = []
        out["errors"].append(f"graph token: {type(exc).__name__}")
    out["status"] = "OK" if not out["errors"] else "PARTIAL"
    out["hint"] = ("Use log_analytics_workspaces[].customerId as workspace_id. azure_roles and graph_app_roles are what the agent can already read; "
                   "scaffold marks those permissions as ALREADY_GRANTED.")
    return out


_ENV_CACHE = {}


def _env_cached():
    if "env" not in _ENV_CACHE:
        try:
            _ENV_CACHE["env"] = _environment()
        except Exception as exc:
            _ENV_CACHE["env"] = {"status": "ERROR", "message": f"{type(exc).__name__}: {str(exc)[:300]}"}
    return _ENV_CACHE["env"]


def _live_possible():
    return bool(os.environ.get("AZURE_CLIENT_ID") and (os.environ.get("IDENTITY_ENDPOINT") or os.environ.get("MSI_ENDPOINT")))


# ----------------------------------------------------------------------------- operations
def _parse_spec(spec_json):
    if isinstance(spec_json, dict):
        return spec_json, None
    text = (spec_json or "").strip()
    fence = re.search(r"```(?:json)?\s*(\{.*\})\s*```", text, re.S)
    if fence:
        text = fence.group(1)
    if not text:
        return None, {"status": "INVALID", "errors": [{"path": "spec_json", "error": "empty", "fix": "call operation=catalog and start from a recipe"}]}
    try:
        return json.loads(text), None
    except json.JSONDecodeError as exc:
        return None, {"status": "INVALID", "errors": [{"path": "spec_json", "error": f"not valid JSON: {exc.msg} at line {exc.lineno} col {exc.colno}",
                                                       "fix": "send strict JSON (double quotes, no comments, no trailing commas)"}]}


def _auto_keys(config, discover):
    picked = {}
    preferred = ["id", "resourceId", "_ResourceId", "ResourceId", "Computer", "appId", "userPrincipalName", "name", "displayName"]
    for s in (discover or {}).get("sources", []):
        if s["id"] in config["keys"] or s.get("status") != "OK":
            continue
        cols = [c["name"] for c in s.get("columns", [])]
        for p in preferred:
            if p in cols:
                picked[s["id"]] = [p]
                break
    return picked


def _probe(spec):
    config, meta, errors, warnings = _validate(spec)
    if errors:
        return {"status": "INVALID", "errors": errors, "warnings": warnings}
    pending = _walk_placeholders(config["sources"])
    if pending:
        return {"status": "NEEDS_INPUT", "pending_inputs": pending, "message": "Fill the placeholders in sources (operation environment lists workspaces, storage, subscriptions)."}
    if not _live_possible():
        return {"status": "NO_IDENTITY", "message": "probe must run inside Azure SRE Agent (managed identity not available)."}
    logo = _brand_resolve(spec.get("brand"), config, warnings)
    code = _build_code(config, meta, logo)
    _, discover, elapsed = _run(code, "discover")
    env = _env_cached()
    perms = _permissions(config, env if env.get("status") in ("OK", "PARTIAL") else None)
    failing = [s for s in discover.get("sources", []) if s.get("status") != "OK"]
    return {"status": discover.get("status"), "elapsed_s": elapsed, "sources": discover.get("sources"), "field_check": _field_check(config, discover),
            "suggested_keys": _auto_keys(config, discover),
            "permission_fixes": [p for p in perms if p["status"] == "TO_GRANT"] if any(s.get("status") in ("FORBIDDEN", "UNAUTHORIZED") for s in failing) else [],
            "warnings": warnings, "error": discover.get("error"), "trace": discover.get("trace")}


def _scaffold(spec):
    config, meta, errors, warnings = _validate(spec)
    if errors:
        return {"status": "INVALID", "errors": errors, "warnings": warnings,
                "next": "Fix every error (path + fix) and call scaffold again with the corrected spec."}
    pending = _walk_placeholders({"sources": config["sources"], "publish": config.get("publish")})
    logo = _brand_resolve(spec.get("brand"), config, warnings)
    env = _env_cached() if _live_possible() else None
    env_ok = bool(env and env.get("status") in ("OK", "PARTIAL"))
    verification, live = {}, None
    if not pending and _live_possible():
        code0 = _build_code(config, meta, logo)
        _, live, live_s = _run(code0, "discover")
        if not config["keys"]:
            config["keys"] = _auto_keys(config, live)
            if config["keys"]:
                warnings.append(f"keys were not given: picked {config['keys']} from live columns.")
        verification["live_discover"] = f"{live.get('status')} in {live_s}s - " + "; ".join(
            f"{s['id']}: {s.get('status')}" + (f" ({s.get('rows', 0)} rows, {len(s.get('columns', []))} columns)" if s.get("status") == "OK" else f" - {str(s.get('error'))[:160]}")
            for s in live.get("sources", [])) if live.get("sources") else f"{live.get('status')}: {live.get('error') or live.get('message')}"
    elif pending:
        verification["live_discover"] = "NOT RUN - placeholders to fill: " + ", ".join(p["path"] for p in pending)
    else:
        verification["live_discover"] = "NOT RUN - no managed identity here (run self_test + discover in Builder)"
    code = _build_code(config, meta, logo)
    lint = _lint(code)
    verification["lint"] = lint["status"] + (": " + "; ".join(lint["errors"]) if lint["errors"] else "")
    if lint["status"] != "PASS":
        return {"status": "FAILED", "stage": "lint", "lint": lint, "verification": verification}
    ns, selftest, st_s = _run(code, "self_test")
    if selftest.get("status") != "SIMULATED":
        return {"status": "FAILED", "stage": "self_test", "self_test": selftest, "verification": verification,
                "next": "Usually a condition/field mismatch: check the error, fix the spec and scaffold again."}
    fired, silent = _rule_coverage(ns, config)
    verification["self_test"] = (f"SIMULATED OK in {st_s}s - network blocked, {len(fired)}/{len(config['rules'])} rules fired on synthetic data, "
                                 f"{len(selftest.get('kpis', []))} KPIs, comparison with a simulated previous run, branded HTML + "
                                 f"{'PDF' if selftest.get('pdf') == 'OK' else 'no PDF (' + str(selftest.get('pdf')) + ')'} + CSV/JSON written")
    if silent:
        warnings.append("Rules that never fired on synthetic data (check the condition, or add sample_rows to the source): " + ", ".join(silent))
    field_check = _field_check(config, live) if live else []
    for fc in field_check:
        if fc["status"] == "MISSING_FIELDS":
            warnings.append(f"Live columns of '{fc['dataset']}' do not include: " + ", ".join(
                m["field"] + (f" (did you mean {m['did_you_mean']})" if m["did_you_mean"] else "") for m in fc["missing"]))
    if field_check:
        verification["field_check"] = "; ".join(f"{fc['dataset']}: {fc['status']}" for fc in field_check)
    perms = _permissions(config, env if env_ok else None)
    folder = Path.cwd() / "sre-usecase-builder" / meta["name"]
    folder.mkdir(parents=True, exist_ok=True)
    code_name = f"{meta['tool']}.py"
    docs = {code_name: code, f"{meta['name']}-BUILDER-BLOCKS.md": _blocks_md(config, meta, code, lint),
            f"{meta['name']}-SETUP.md": _setup_md(config, meta, perms, verification, code_name),
            f"{meta['name']}-spec.json": json.dumps(spec, ensure_ascii=False, indent=2)}
    for fname, content in docs.items():
        (folder / fname).write_text(content, encoding="utf-8")
    match = re.search(r"/tmp/ThreadFiles/([0-9a-fA-F-]{36})", Path.cwd().as_posix())
    link = (lambda f: f"/api/files/tmp/ThreadFiles/{match.group(1)}/sre-usecase-builder/{meta['name']}/{quote(f)}") if match else (lambda f: str(folder / f))
    live_ok = bool(live and live.get("status") == "OK" and all(fc["status"] in ("OK", "NO_ROWS") for fc in field_check))
    status = "READY_WITH_INPUTS" if pending else "READY_LIVE_VERIFIED" if live_ok else "READY_LIVE_ISSUES" if live else "READY"
    config_text = code[code.index("CONFIG = "): code.index("\n\n", code.index("CONFIG = "))]
    full = {
        "status": status,
        "meaning": {"READY_LIVE_VERIFIED": "lint + self_test passed and live data was read with the expected fields",
                    "READY_LIVE_ISSUES": "code is correct; live read failed or fields differ - see verification/permissions/warnings",
                    "READY_WITH_INPUTS": "code is correct; fill pending_inputs in CONFIG before the live run",
                    "READY": "lint + self_test passed; live check must be done in Builder (discover)"}[status],
        "names": {k: meta[k] for k in ("tool", "skill", "agent", "task", "cron")},
        "verification": verification, "pending_inputs": pending, "permissions": perms, "warnings": warnings,
        "self_test_report": selftest.get("files"), "self_test_kpis": selftest.get("kpis"),
        "files": {f: link(f) for f in docs},
        "blocks": {
            "python_tool": {"name": meta["tool"], "description": _tool_description(config, meta), "timeout_seconds": 300,
                            "parameters": TOOL_PARAMS, "code_file": link(code_name), "code_bytes": len(code.encode()),
                            "code_sha256": hashlib.sha256(code.encode()).hexdigest()[:16], "config_section": config_text[:6000]},
            "skill": {"name": meta["skill"], "tools": [meta["tool"]], "skill_md": _skill_md(config, meta)},
            "subagent": {"name": meta["agent"], "description": (meta["description"] or config["title"])[:300], "tools": [meta["tool"]],
                         "skills": [meta["skill"]], "instructions": _instructions(config, meta)},
            "scheduled_task": {"name": meta["task"], "agent": meta["agent"], "cron_utc": meta["cron"], "prompt": _task_prompt(config, meta)},
        },
        "test_prompts": _test_prompts(config, meta),
    }
    (folder / f"{meta['name']}-scaffold.json").write_text(json.dumps(full, ensure_ascii=False, indent=1, default=str), encoding="utf-8")
    html_report = next((v for k, v in (selftest.get("files") or {}).items() if k.endswith(".html")), None)
    pdf_report = next((v for k, v in (selftest.get("files") or {}).items() if k.endswith(".pdf")), None)
    brand = config.get("brand") or {}
    compact = {
        "status": status, "meaning": full["meaning"], "names": full["names"], "verification": verification,
        "pending_inputs": [p["path"] for p in pending],
        "permissions": [{"status": p["status"], "need": p["need"], "scope": p["scope"]} for p in perms],
        "warnings": warnings,
        "self_test_report": html_report, "self_test_pdf": pdf_report,
        "design": {"brand": brand.get("name") or "default (Azure SRE Agent)", "logo": "embedded" if logo else "wordmark",
                   "primary": brand.get("primary"), "accent": brand.get("accent"), "font": brand.get("font", "plex"),
                   "charts": len(config.get("charts", []))},
        "files": full["files"],
        "get_parts": [f"{meta['name']}/{p}" for p in GET_PARTS],
        "next": (f"Now call operation=get with spec_json='{meta['name']}/answer' (pages 1..n via '/answer/2'...) - it returns the complete "
                 "Builder blocks, permission commands and test steps ready to present. Single parts: " + ", ".join(GET_PARTS) + "."),
    }
    return _fit(compact, "scaffold-" + meta["name"])


# ----------------------------------------------------------------------------- answer budget
# Azure SRE Agent hands only ~4,000 characters of a tool result to the model. Every kit answer stays inside this budget;
# large content is saved to files and served page by page with operation=get.
RESULT_BUDGET = 3800
PAGE_CHARS = 3200
GET_PARTS = ["answer", "tool", "config", "skill", "subagent", "task", "permissions", "tests", "setup", "code", "spec"]


def _size(value):
    return len(json.dumps(value, ensure_ascii=False, default=str))


def _shrink_once(node):
    best = None

    def walk(parent, key, value):
        nonlocal best
        if isinstance(value, dict):
            if parent is not None and len([k for k in value if k != "_more_keys"]) > 1:
                size = _size(value)
                if not best or size > best[0]:
                    best = (size, parent, key, "dict")
            for k, v in value.items():
                if k not in ("result_truncated", "status", "next"):
                    walk(value, k, v)
        elif isinstance(value, list):
            if len(value) > 1:
                size = _size(value)
                if not best or size > best[0]:
                    best = (size, parent, key, "list")
            for i, v in enumerate(value):
                walk(value, i, v)
        elif isinstance(value, str) and len(value) > 200 and (not best or len(value) > best[0]):
            best = (len(value), parent, key, "str")

    walk(None, None, node)
    if not best:
        return False
    _, parent, key, kind = best
    value = parent[key]
    if kind == "dict":
        real = [k for k in value if k != "_more_keys"]
        keep = real[:max(1, len(real) // 2)]
        parent[key] = dict({k: value[k] for k in keep}, _more_keys=value.get("_more_keys", 0) + len(real) - len(keep))
        return True
    parent[key] = value[:max(1, len(value) // 2)] if kind == "list" else value[:max(160, len(value) // 2)] + "..."
    return True


def _thread_link(path):
    match = re.search(r"/tmp/ThreadFiles/([0-9a-fA-F-]{36})/(.*)$", Path(path).as_posix())
    return f"/api/files/tmp/ThreadFiles/{match.group(1)}/{quote(match.group(2))}" if match else str(path)


def _fit(result, label):
    if _size(result) <= RESULT_BUDGET:
        return result
    link = None
    try:
        folder = Path.cwd() / "sre-usecase-builder" / "_results"
        folder.mkdir(parents=True, exist_ok=True)
        path = folder / f"{re.sub(r'[^a-zA-Z0-9_-]', '_', label)}-{datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%S%fZ')}.json"
        path.write_text(json.dumps(result, ensure_ascii=False, indent=1, default=str), encoding="utf-8")
        link = _thread_link(path)
    except OSError:
        pass
    out = dict({"result_truncated": {"full_result": link, "note": "Shortened to fit the agent; the full result is in full_result."}},
               **json.loads(json.dumps(result, ensure_ascii=False, default=str)))
    for _ in range(400):
        if _size(out) <= RESULT_BUDGET or not _shrink_once(out):
            break
    if _size(out) > RESULT_BUDGET:
        out = {k: out[k] for k in ("result_truncated", "status", "error_code", "message", "next") if k in out}
        out["omitted_keys"] = [k for k in result if k not in out]
    return out


def _env_summary(env):
    if env.get("status") not in ("OK", "PARTIAL"):
        return env
    short = lambda scope: re.sub(r"^/subscriptions/([0-9a-f]{8})[0-9a-f-]+", r"sub \1..", scope or "")
    out = {"status": env["status"], "identity": env.get("identity"),
           "subscriptions": env.get("subscriptions", [])[:10],
           "log_analytics_workspaces": [{"name": w.get("name"), "customerId": w.get("customerId"), "resourceGroup": w.get("resourceGroup")}
                                        for w in env.get("log_analytics_workspaces", [])][:12],
           "storage_accounts": [s.get("name") for s in env.get("storage_accounts", [])][:12],
           "kusto_clusters": [{"name": k.get("name"), "uri": k.get("uri")} for k in env.get("kusto_clusters", [])][:5],
           "azure_roles": sorted({f"{r['role']} @ {short(r['scope'])}" for r in env.get("azure_roles", [])})[:15],
           "graph_app_roles": env.get("graph_app_roles", []),
           "errors": env.get("errors", [])[:3],
           "hint": env.get("hint")}
    return _fit(out, "environment")


def _page(text, page):
    pages = max(1, -(-len(text) // PAGE_CHARS))
    page = min(max(1, page), pages)
    chunk = text[(page - 1) * PAGE_CHARS: page * PAGE_CHARS]
    return chunk, page, pages


def _answer_md(full):
    b = full["blocks"]
    lines = ["## Builder blocks", "", f"Full copy/paste file: {full['files'].get(next(k for k in full['files'] if k.endswith('-BUILDER-BLOCKS.md')))}", "",
             f"### Block 1 - Python tool `{b['python_tool']['name']}`", f"- Description: {b['python_tool']['description']}",
             "- Where: Builder > Agent Canvas > Create > Tool > Python tool (Enable Azure Identity OFF; run one Test before Create)",
             f"- Timeout: {b['python_tool']['timeout_seconds']} s", f"- Code file: {b['python_tool']['code_file']}",
             "- Parameters: " + "; ".join(f"`{p['name']}` ({p['type']}, default {p.get('value')!r}) {p['description']}" for p in b["python_tool"]["parameters"]),
             "", "CONFIG section of the code (edit values here):", "```python", b["python_tool"]["config_section"], "```", "",
             f"### Block 2 - Skill `{b['skill']['name']}` (tools: {', '.join(b['skill']['tools'])})", "Where: Builder > Agent Canvas > Create > Skill", "```markdown", b["skill"]["skill_md"], "```", "",
             f"### Block 3 - Subagent `{b['subagent']['name']}` (tools: {', '.join(b['subagent']['tools'])}; skills: {', '.join(b['subagent']['skills'])})",
             "Where: Builder > Agent Canvas > Create > Custom Agent", f"Description: {b['subagent']['description']}", "```text", b["subagent"]["instructions"], "```", "",
             f"### Block 4 - Scheduled task `{b['scheduled_task']['name']}` (agent {b['scheduled_task']['agent']}, cron UTC `{b['scheduled_task']['cron_utc']}`)",
             "Where: Automation > Create > Scheduled task (Frequency: Custom cron)", "```text", b["scheduled_task"]["prompt"], "```", "", "## Permissions"]
    for p in full["permissions"]:
        lines += [f"- **{p['status']}** {p['need']} on `{p['scope']}` - {p.get('why', '')}"]
        if p.get("command"):
            lines += ["```", p["command"], "```"]
    lines += ["", "## Test in Builder", "1. mode=self_test -> SIMULATED + HTML link", "2. mode=discover -> every source OK with real columns",
              "3. mode=report publish=no -> OK, open the HTML", "4. mode=report publish=yes (if publish is configured) -> published[].status OK",
              "", "Test prompts:"] + [f"- `{t}`" for t in full["test_prompts"]]
    return "\n".join(lines)


def _get(ref):
    parts = [p for p in (ref or "").strip().strip('"').split("/") if p]
    if len(parts) < 2:
        return {"status": "INVALID", "message": "spec_json must be '<use-case name>/<part>[/<page>]'", "parts": GET_PARTS}
    name, part = parts[0], parts[1].lower()
    page = int(parts[2]) if len(parts) > 2 and parts[2].isdigit() else 1
    folder = Path.cwd() / "sre-usecase-builder" / name
    path = folder / f"{name}-scaffold.json"
    if not path.exists():
        return {"status": "NOT_FOUND", "message": f"No scaffold for '{name}' in this thread. Run scaffold first."}
    full = json.loads(path.read_text(encoding="utf-8"))
    b = full["blocks"]
    texts = {
        "answer": lambda: _answer_md(full),
        "tool": lambda: json.dumps({k: v for k, v in b["python_tool"].items() if k != "config_section"}, ensure_ascii=False, indent=1),
        "config": lambda: b["python_tool"]["config_section"],
        "skill": lambda: b["skill"]["skill_md"],
        "subagent": lambda: json.dumps({k: v for k, v in b["subagent"].items() if k != "instructions"}, ensure_ascii=False) + "\n\n" + b["subagent"]["instructions"],
        "task": lambda: json.dumps(b["scheduled_task"], ensure_ascii=False, indent=1),
        "permissions": lambda: json.dumps(full["permissions"], ensure_ascii=False, indent=1),
        "tests": lambda: "\n".join(full["test_prompts"]),
        "setup": lambda: (folder / f"{name}-SETUP.md").read_text(encoding="utf-8"),
        "code": lambda: (folder / f"{full['names']['tool']}.py").read_text(encoding="utf-8"),
        "spec": lambda: (folder / f"{name}-spec.json").read_text(encoding="utf-8"),
    }
    if part not in texts:
        return {"status": "INVALID", "message": f"Unknown part '{part}'", "parts": GET_PARTS}
    chunk, page, pages = _page(texts[part](), page)
    return {"status": "OK", "part": f"{name}/{part}", "page": page, "pages": pages,
            "next": f"call get with spec_json='{name}/{part}/{page + 1}'" if page < pages else "complete", "content": chunk}


def _kit_main(operation="catalog", spec_json="", code=""):
    op = (operation or "catalog").strip().lower()
    try:
        if op == "catalog":
            return _fit(_catalog_detail(spec_json) if (spec_json or "").strip() else _catalog_index(), "catalog")
        if op == "environment":
            return _env_summary(_env_cached())
        if op == "lint":
            return _fit(_lint(code or ""), "lint")
        if op == "get":
            return _get(spec_json)
        if op == "brand":
            return _fit(_brand_op(spec_json), "brand")
        if op in ("probe", "scaffold"):
            spec, error = _parse_spec(spec_json)
            if error:
                return error
            return _fit(_probe(spec) if op == "probe" else _scaffold(spec), op)
        return {"status": "INVALID", "message": "operation must be catalog, environment, brand, probe, scaffold, get or lint"}
    except Exception as exc:
        return {"status": "KIT_ERROR", "error": f"{type(exc).__name__}: {exc}", "trace": traceback.format_exc()[-1500:],
                "next": "Report this error; retry scaffold once with a simpler spec."}


